1. The block
Four fully connected layers turn the window into a hidden vector; two linear heads turn that into the backcast and the forecast. This is the generic block. The paper also has interpretable blocks whose heads are fixed polynomial (trend) and Fourier (seasonality) bases, so their outputs can be read as components.


class Block(nn.Module):
    def __init__(self, width: int = 256, layers: int = 4):
        super().__init__()
        dims = [L] + [width] * layers
        self.fc = nn.Sequential(*[m for a, b in zip(dims, dims[1:]) for m in (nn.Linear(a, b), nn.ReLU())])
        self.backcast = nn.Linear(width, L)
        self.forecast = nn.Linear(width, H)

    def forward(self, x):
        h = self.fc(x)
        return self.backcast(h), self.forecast(h)


class NBeats(nn.Module):
    def __init__(self, n_blocks: int = 6, width: int = 256):
        super().__init__()
        self.blocks = nn.ModuleList(Block(width) for _ in range(n_blocks))

    def forward(self, x):
        # Instance normalisation: each window is forecast in units of its own level and spread.
        mu, sd = x.mean(1, keepdim=True), x.std(1, keepdim=True) + 1e-3
        residual, forecast = (x - mu) / sd, 0.0
        for block in self.blocks:
            back, fore = block(residual)
            residual = residual - back      # pass on what this block did not explain
            forecast = forecast + fore      # and add its forecast to the total
        return forecast * sd + mu

1. Recursive
One model learns the next hour from the hours just before it. At forecast time its own prediction for hour 1 becomes lag1 for hour 2, and so on.


def one_step_features(s: pd.Series) -&gt; pd.DataFrame:
    X = pd.DataFrame({f"lag{l}": s.shift(l) for l in LAGS}, index=s.index)
    return pd.concat([X, calendar(s.index).set_index(s.index)], axis=1)


one_step = lgb.LGBMRegressor(**PARAMS).fit(one_step_features(train).iloc[336:], train.iloc[336:])


def recursive(history, horizon):
    s = history.iloc[-340:].copy()
    preds = []
    for ts in future_index(history, horizon):
        s.loc[ts] = np.nan
        pred = one_step.predict(one_step_features(s).iloc[[-1]])[0]
        s.loc[ts] = pred  # the guess becomes an input for the next hour
        preds.append(pred)
    return np.array(preds)

2. Direct
Model h (for h = 1 to 24) is trained on rows where the inputs are the values known at an origin and the target is the value h hours later. Each model uses the freshest values available to it, and none of them ever sees a prediction.


def origin_features(s: pd.Series) -&gt; pd.DataFrame:
    "Values known at the end of each hour: the latest value (lag 1 for the next hour) and older lags."
    return pd.DataFrame({f"lag{l}": s.shift(l - 1) for l in LAGS}, index=s.index)


base = origin_features(train)
direct_models = {}
for h in range(1, 25):
    target = train.shift(-h)
    X = pd.concat([base, calendar(train.index + pd.Timedelta(hours=h)).set_index(train.index)], axis=1)
    ok = X.notna().all(axis=1) & target.notna()
    direct_models[h] = lgb.LGBMRegressor(**PARAMS).fit(X[ok], target[ok])


def direct(history, horizon):
    known = origin_features(history.iloc[-340:]).iloc[[-1]].reset_index(drop=True)
    out = []
    for h in range(1, horizon + 1):
        ts = history.index[-1] + pd.Timedelta(hours=h)
        out.append(direct_models[h].predict(pd.concat([known, calendar(pd.DatetimeIndex([ts]))], axis=1))[0])
    return np.array(out)

4. One model, lags of at least 24 hours
The sidestep: the same LightGBM, but only lags 24, 48, 168 and 336 hours, so the features of every hour of the day ahead are known at the origin. One model, no recursion.


SAFE = [24, 48, 168, 336]


def safe_features(s):
    X = pd.DataFrame({f"lag{l}": s.shift(l) for l in SAFE}, index=s.index)
    return pd.concat([X, calendar(s.index).set_index(s.index)], axis=1)


safe_model = lgb.LGBMRegressor(**PARAMS).fit(safe_features(train).iloc[336:], train.iloc[336:])


def safe_lags(history, horizon):
    ext = pd.concat([history.iloc[-340:], pd.Series(np.nan, index=future_index(history, horizon))])
    return safe_model.predict(safe_features(ext).iloc[-horizon:])

2. With calendar covariates
Hour of day and weekday are known for every future hour, so they can be passed as known-future covariates: their history alongside the target’s, and their future values for the forecast hours.


def calendar(index):
    return {"hour": index.hour.to_numpy(np.float32), "dow": index.dayofweek.to_numpy(np.float32)}


def with_calendar(history, horizon):
    x = history.iloc[-CTX:]
    item = {"target": x.to_numpy(np.float32), "past_covariates": calendar(x.index),
            "future_covariates": calendar(future_index(history, horizon))}
    return median(pipe.predict_quantiles([item], prediction_length=horizon, quantile_levels=[0.5]))


cal_score, _ = run("Chronos-2, + calendar", with_calendar)

Chronos-2, + calendar: skill +21.6%, MASE 0.640, 0.7 s for 30 forecasts
